use crate::{error::{Error,Result},preferences::{self,AutostartStatus,SettingsReply,RunChange},user_store::Store};
use super::identity::wide;
use windows_sys::Win32::{System::Registry::*,Foundation::*};
const RUN:&str=r"Software\Microsoft\Windows\CurrentVersion\Run";
const APPROVED:&str=r"Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run";
const NAME:&str="KatClient";
struct Key(HKEY);impl Drop for Key{fn drop(&mut self){unsafe{RegCloseKey(self.0);}}}
fn open(path:&str,write:bool)->Result<Option<Key>>{unsafe{let mut key=std::ptr::null_mut();let status=if write{RegCreateKeyExW(HKEY_CURRENT_USER,wide(path).as_ptr(),0,std::ptr::null(),0,KEY_QUERY_VALUE|KEY_SET_VALUE,std::ptr::null(),&mut key,std::ptr::null_mut())}else{RegOpenKeyExW(HKEY_CURRENT_USER,wide(path).as_ptr(),0,KEY_QUERY_VALUE,&mut key)};if status==ERROR_FILE_NOT_FOUND{return Ok(None);}if status!=0{return Err(Error::new("AUTOSTART_REGISTRY","Cannot access the current-user startup setting"));}Ok(Some(Key(key)))}}
fn raw(path:&str)->Result<Option<(u32,Vec<u8>)>>{let Some(k)=open(path,false)?else{return Ok(None)};unsafe{let(mut kind,mut len)=(0,0);let rc=RegQueryValueExW(k.0,wide(NAME).as_ptr(),std::ptr::null(),&mut kind,std::ptr::null_mut(),&mut len);if rc==ERROR_FILE_NOT_FOUND{return Ok(None);}if rc!=0||len>65536{return Err(Error::new("AUTOSTART_REGISTRY","Cannot read bounded startup value"));}let mut bytes=vec![0u8;len as usize];if RegQueryValueExW(k.0,wide(NAME).as_ptr(),std::ptr::null(),&mut kind,bytes.as_mut_ptr(),&mut len)!=0{return Err(Error::new("AUTOSTART_REGISTRY","Cannot read startup value"));}bytes.truncate(len as usize);Ok(Some((kind,bytes)))}}
fn current()->Result<Option<String>>{match raw(RUN)?{None=>Ok(None),Some((kind,b))=>{if kind!=REG_SZ||b.len()%2!=0{return Err(Error::new("AUTOSTART_FOREIGN","Unrecognized startup value"));}let w:Vec<u16>=b.chunks_exact(2).map(|x|u16::from_le_bytes([x[0],x[1]])).collect();let end=w.iter().position(|v|*v==0).unwrap_or(w.len());if w[end..].iter().any(|v|*v!=0){return Err(Error::new("AUTOSTART_FOREIGN","Unrecognized startup value"));}String::from_utf16(&w[..end]).map(Some).map_err(|_|Error::new("AUTOSTART_FOREIGN","Unrecognized startup value"))}}}
fn disabled()->Result<bool>{match raw(APPROVED)?{None=>Ok(false),Some((kind,b))if kind==REG_BINARY&&b.len()>=12=>match b[0]{2|6=>Ok(false),3|7=>Ok(true),_=>Err(Error::new("AUTOSTART_STATE","Unknown Windows startup approval state"))},_=>Err(Error::new("AUTOSTART_STATE","Unknown Windows startup approval format"))}}
fn canonical()->Result<String>{let p=std::fs::canonicalize(std::env::current_exe().map_err(|e|Error::io("AUTOSTART_PATH",&e))?).map_err(|e|Error::io("AUTOSTART_PATH",&e))?;if p.file_name().and_then(|n|n.to_str())!=Some("kat-desktop.exe"){return Err(Error::new("AUTOSTART_PATH","Only the fixed Kat GUI may start at login"));}let p=p.to_str().ok_or_else(||Error::new("AUTOSTART_PATH","Invalid executable path"))?.strip_prefix(r"\\?\").unwrap_or_else(||p.to_str().unwrap());if p.contains('"'){return Err(Error::new("AUTOSTART_PATH","Invalid executable quoting"));}Ok(format!("\"{p}\" --autostart"))}
fn write(value:Option<&str>)->Result<()>{let k=open(RUN,true)?.ok_or_else(||Error::new("AUTOSTART_REGISTRY","Cannot open startup key"))?;unsafe{let rc=if let Some(value)=value{let w=wide(value);RegSetValueExW(k.0,wide(NAME).as_ptr(),0,REG_SZ,w.as_ptr().cast(),(w.len()*2)as u32)}else{RegDeleteValueW(k.0,wide(NAME).as_ptr())};if rc!=0&&rc!=ERROR_FILE_NOT_FOUND{return Err(Error::new("AUTOSTART_REGISTRY","Cannot change current-user startup value"));}}Ok(())}
#[derive(Clone,serde::Serialize,serde::Deserialize)]#[serde(deny_unknown_fields)]struct Owner{command:String}
fn owner(s:&Store)->Result<Option<Owner>>{s.load("desktop-autostart-owner.json",65536)}
pub fn status(s:&Store)->AutostartStatus{let result=(||{let canonical=canonical()?;let owned=owner(s)?;let c=current()?;if c.is_none(){return Ok(AutostartStatus{enabled:false,state:"off".into(),error:None});}if c.as_deref()!=Some(&canonical)&&c.as_deref()!=owned.as_ref().map(|o|o.command.as_str()){return Ok(AutostartStatus{enabled:false,state:"foreign".into(),error:Some("AUTOSTART_FOREIGN".into())});}if disabled()?{Ok(AutostartStatus{enabled:false,state:"disabled".into(),error:None})}else{Ok(AutostartStatus{enabled:true,state:"on".into(),error:None})}})();result.unwrap_or_else(|e:Error|AutostartStatus{enabled:false,state:if e.code=="AUTOSTART_FOREIGN"{"foreign"}else{"error"}.into(),error:Some(e.code)})}
pub fn get(s:&Store)->Result<SettingsReply>{Ok(SettingsReply{preferences:preferences::load(s)?,autostart:status(s)})}
pub fn set(s:&Store,patch:preferences::Patch)->Result<SettingsReply>{
 super::identity::require_normal_user()?;let before=preferences::load(s)?;let launch=patch.launch_at_login;let after=patch.apply(before);
 if launch.is_none(){preferences::save(s,&after)?;return get(s);}
 let canonical=canonical()?;let old_owner=owner(s)?;let old=current()?;let change=preferences::autostart_change(old.as_deref(),old_owner.as_ref().map(|o|o.command.as_str()),&canonical,after.launch_at_login)?;
 let installed=match &change{RunChange::Keep=>old.clone(),RunChange::Set(v)=>Some(v.clone()),RunChange::Remove=>None};
 preferences::transaction(||{if current()?!=old{return Err(Error::new("AUTOSTART_CHANGED","Startup value changed before update"));}match &change{RunChange::Keep=>{},RunChange::Set(v)=>write(Some(v))?,RunChange::Remove=>write(None)?,}Ok(())},||{
   s.save("desktop-autostart-owner.json",&Owner{command:canonical.clone()},65536)?;preferences::save(s,&after)
 },|_|{if current()?!=installed{return Err(Error::new("AUTOSTART_CHANGED","Startup value changed; not overwriting another application"));}write(old.as_deref())?;if let Some(o)=old_owner{s.save("desktop-autostart-owner.json",&o,65536)?;}else if s.read("desktop-autostart-owner.json",65536)?.is_some(){s.remove("desktop-autostart-owner.json")?;}Ok(())})?;
 get(s)
}

/// Migrate only a still-owned existing Run entry after moving the installed application.
/// Do not create missing/disabled entries or change Windows StartupApproved data on launch.
pub fn migrate_owned(s:&Store)->Result<()>{let p=preferences::load(s)?;if !p.launch_at_login{return Ok(());}let new=canonical()?;let previous=owner(s)?;if let Some(o)=previous{if o.command!=new&&current()?.as_deref()==Some(o.command.as_str()){set(s,preferences::Patch{launch_at_login:Some(true),..Default::default()})?;}}Ok(())}
